def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            wall_dirs = set()
            touched_edges = set()
            for x, y in cells:
                if x == 0: touched_edges.add('top')
                if x == h - 1: touched_edges.add('bottom')
                if y == 0: touched_edges.add('left')
                if y == w - 1: touched_edges.add('right')
                for dx, dy, direction in ((1, 0, 'down'), (-1, 0, 'up'), (0, 1, 'right'), (0, -1, 'left')):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 5:
                        wall_dirs.add(direction)
            # Shade the compact pockets bounded by the 5 strokes; tiny isolated
            # pockets are also marked, even when they touch a corner.
            if len(cells) <= 2 or (len(touched_edges) <= 2 and len(wall_dirs) >= 3):
                color = 7 if len(cells) <= 4 else 8
                for x, y in cells:
                    out[x][y] = color
    return out
